import type { Role } from "@/lib/types";

export type TestAction = "list" | "create" | "delete";

export interface TestRuleInput {
  action: TestAction;
  role: string;
}

export interface TestRuleDecision {
  allowed: boolean;
  reason?: string;
}

/** Role → allowed actions matrix. Extend as needed. */
const ALLOWED: Record<TestAction, Role[]> = {
  list:   ["sysadmin", "admin"],
  create: ["sysadmin", "admin"],
  delete: ["sysadmin"],
};

export function applyTestRules(input: TestRuleInput): TestRuleDecision {
  const allowed = ALLOWED[input.action].includes(input.role as Role);
  return allowed
    ? { allowed: true }
    : { allowed: false, reason: `role ${input.role} cannot ${input.action}` };
}
